// ========================================================================
// FHIR COMPLEX DATA TYPES
// ========================================================================
//
// These composite types combine primitives to create meaningful healthcare concepts.
// Enhanced with dataset-specific patterns and validation insights.

/**
 * Coding - Reference to a code defined by a terminology system
 * 
 * DATASET USAGE PATTERNS:
 * - System URIs: "http://loinc.org", "http://snomed.info/sct", "urn:oid:2.16.840.1.113883.6.238"
 * - Display names: "Body Height", "Vital signs", "White", "Not Hispanic or Latino"
 * - Version: Rarely populated in this dataset
 * - UserSelected: Typically null (automated system selection)
 * 
 * COMMON EXAMPLES FROM DATASET:
 * - LOINC: {system: "http://loinc.org", code: "8302-2", display: "Body Height"}
 * - SNOMED: {system: "http://snomed.info/sct", code: "185347001", display: "..."}
 * - Race/Ethnicity: {system: "urn:oid:2.16.840.1.113883.6.238", code: "2106-3", display: "White"}
 * 
 * VALIDATION INSIGHTS:
 * - System URIs are always full URLs (not relative like some other URI fields)
 * - Display text matches code meaning consistently
 * - Some codes have numeric patterns (vital signs, labs)
 * - Race/ethnicity codes follow OMB standard patterns
 */
export const Coding = z.object({
  system: FhirUri.optional().describe('Terminology system URI - always full URLs in this dataset'),
  version: FhirString.optional().describe('System version - rarely populated in synthetic data'),
  code: FhirCode.optional().describe('Code value - LOINC, SNOMED, or OMB codes commonly used'),
  display: FhirString.optional().describe('Human readable text - consistently matches code meaning'),
  userSelected: FhirBoolean.optional().describe('User selection flag - typically null in automated systems')
}).describe('Reference to a terminology code - forms backbone of clinical coding');

