/**
 * A concept that may be defined by a formal reference to a terminology or ontology
 * or may be provided by text. This is a common pattern in FHIR.
 */
export const CodeableConcept = z.object({
  coding: z.array(Coding).optional().describe('Code defined by a terminology system'),
  text: FhirString.optional().describe('Plain text representation of the concept')
}).describe('A concept that may be defined by a formal reference to a terminology or ontology');

/**
 * A measured amount (or an amount that can potentially be measured)
 * Note: This is used for observations, medication quantities, etc.
 */
export const Quantity = z.object({
  value: FhirDecimal.optional().describe('Numerical value (with implicit precision)'),
  comparator: z.enum(['<', '<=', '>=', '>', 'ad']).optional().describe('How to understand the value'),
  unit: FhirString.optional().describe('Unit representation'),
  system: FhirUri.optional().describe('System that defines coded unit form'),
  code: FhirCode.optional().describe('Coded form of the unit')
}).describe('A measured amount (or an amount that can potentially be measured)');

/**
 * A time period defined by a start and end date/time
 * Used for encounters, conditions, etc.
 */
export const Period = z.object({
  start: FhirDateTime.optional().describe('Starting time with inclusive boundary'),
  end: FhirDateTime.optional().describe('End time with inclusive boundary, if not ongoing')
}).describe('A time period defined by a start and end date/time');

/**
 * An identifier - identifies some entity uniquely and unambiguously
 * Used for patients, resources, etc.
 */
export const Identifier = z.object({
  use: z.enum(['usual', 'official', 'temp', 'secondary', 'old']).optional().describe('The purpose of this identifier'),
  type: CodeableConcept.optional().describe('Description of identifier'),
  system: FhirUri.optional().describe('The namespace for the identifier value'),
  value: FhirString.optional().describe('The value that is unique'),
  period: Period.optional().describe('Time period when id is/was valid for use'),
  assigner: z.object({
    reference: FhirString.optional(),
    display: FhirString.optional()
  }).optional().describe('Organization that issued id')
}).describe('An identifier - identifies some entity uniquely and unambiguously');

/**
 * A human name with the ability to identify parts and usage
 * Used for patients, practitioners, etc.
 */
export const HumanName = z.object({
  use: z.enum(['usual', 'official', 'temp', 'nickname', 'anonymous', 'old', 'maiden']).optional().describe('Identifies the purpose for this name'),
  text: FhirString.optional().describe('Text representation of the full name'),
  family: FhirString.optional().describe('Family name (often called surname)'),
  given: z.array(FhirString).optional().describe('Given names (not always first). Includes middle names'),
  prefix: z.array(FhirString).optional().describe('Parts that come before the name'),
  suffix: z.array(FhirString).optional().describe('Parts that come after the name'),
  period: Period.optional().describe('Time period when name was/is in use')
}).describe('A human name with the ability to identify parts and usage');

/**
 * An address expressed using postal conventions (as opposed to GPS or other location definition formats)
 * Used for patients, organizations, etc.
 */
export const Address = z.object({
  use: z.enum(['home', 'work', 'temp', 'old', 'billing']).optional().describe('The purpose of this address'),
  type: z.enum(['postal', 'physical', 'both']).optional().describe('Distinguishes between physical addresses and mailing addresses'),
  text: FhirString.optional().describe('Text representation of the address'),
  line: z.array(FhirString).optional().describe('Street name, number, direction & P.O. Box etc.'),
  city: FhirString.optional().describe('Name of city, town etc.'),
  district: FhirString.optional().describe('District name (aka county)'),
  state: FhirString.optional().describe('Sub-unit of country (abbreviations ok)'),
  postalCode: FhirString.optional().describe('Postal code for area'),
  country: FhirString.optional().describe('Country (e.g. may be ISO 3166 2 or 3 letter code)'),
  period: Period.optional().describe('Time period when address was/is in use'),
  extension: z.array(z.object({
    url: FhirString.describe('Extension URL (can be relative)'),
    extension: z.array(z.object({
      url: FhirString.describe('Extension property URL (can be relative like "latitude")'),
      valueDecimal: FhirDecimal.optional().describe('Extension decimal value'),
      valueString: FhirString.optional().describe('Extension string value')
    })).optional().describe('Nested extensions')
  })).optional().describe('FHIR extensions for additional data like geolocation')
}).describe('An address expressed using postal conventions');
